'use strict';
const $=s=>document.querySelector(s), KEY='folio-library-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const datePlus=(n)=>{const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const displayDate=s=>new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const uid=()=>crypto.randomUUID();
const quoteOffsets=Object.create(null);
const pagePassages={overview:'treasure',catalog:'enjoyment',members:'happy',loans:'diary',insights:'breakfast',settings:'memory'};
let queryState,queryCache;
function queries(){if(queryState!==state){const loans=state.loans.filter(l=>!l.returned),counts=new Map(),byMember=new Map();for(const l of loans){counts.set(l.bookId,(counts.get(l.bookId)||0)+1);if(!byMember.has(l.memberId))byMember.set(l.memberId,[]);byMember.get(l.memberId).push(l)}queryCache={loans,counts,byMember,books:new Map(state.books.map(b=>[b.id,b])),members:new Map(state.members.map(m=>[m.id,m]))};queryState=state}return queryCache}
function passage(id){return PASSAGES.find(p=>p.id===id)||PASSAGES[0]}
function sourceButton(p,label='Source & context'){return '<button type="button" class="source-link" data-source="'+esc(p.id)+'">'+label+'</button>'}
function passageNote(id,small=false){const p=passage(id);return '<aside class="'+(small?'modal-margin':'literary-note')+'" aria-label="Literary quotation">'+(small?'':'<span class="literary-glyph" aria-hidden="true">“</span>')+'<div class="literary-content">'+(small?'':'<p class="literary-tag">From the shelves</p>')+'<blockquote>'+esc(p.text)+'</blockquote><'+(small?'p':'figcaption')+'>'+esc(p.author)+' · <cite>'+esc(p.work)+'</cite><br>'+sourceButton(p)+'</'+(small?'p':'figcaption')+'></div></aside>'}
function pageNote(){const start=PASSAGES.findIndex(p=>p.id===pagePassages[page]);const p=PASSAGES[(start+(quoteOffsets[page]||0))%PASSAGES.length];return '<section class="page-passage">'+passageNote(p.id).replace('</aside>','<div class="literary-tools"><button type="button" data-another-passage>Another passage</button><button type="button" data-literary-library>Browse all</button></div></aside>')+'</section>'}
function showSource(id){const p=passage(id);$('#source-title').textContent='The words, and their source.';$('#source-body').innerHTML='<p class="literary-tag">'+(p.excerpt?'Verbatim excerpt':'Verbatim quotation')+'</p><blockquote class="source-quote">'+esc(p.text)+'</blockquote><div class="source-meta"><strong>'+esc(p.author)+'</strong><br><cite>'+esc(p.work)+'</cite><br>'+esc(p.location)+'</div><p class="source-context">'+esc(p.context)+'</p><a class="button primary" href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">Read the original text</a>';$('#source-dialog').showModal()}
function showPassages(){$('#source-title').textContent='The literary collection.';$('#source-body').innerHTML='<p class="subtitle">Twelve passages from eight classic works. Each quotation links to the text it came from.</p><br><div class="passage-shelf">'+PASSAGES.map(p=>'<article class="passage-card"><blockquote>'+esc(p.text)+'</blockquote><p><strong>'+esc(p.author)+'</strong> · <cite>'+esc(p.work)+'</cite><br>'+esc(p.location)+(p.excerpt?' · excerpt':'')+'</p><p>'+esc(p.context)+'</p><a class="source-link" target="_blank" rel="noopener noreferrer" href="'+esc(p.url)+'">Read the source</a></article>').join('')+'</div>';$('#source-dialog').showModal()}

const seed=()=>({version:1,books:[
['b1','The Midnight Library','Matt Haig','Fiction',3,'#273d3c','✦','A novel about all the lives we could live.'],
['b2','Atomic Habits','James Clear','Personal growth',4,'#e4ddc8','◌','Small changes, remarkable results.'],
['b3','The Psychology of Money','Morgan Housel','Finance',2,'#ebe5d5','♙','Timeless lessons on wealth, greed, and happiness.'],
['b4','Ikigai','Héctor García','Personal growth',3,'#b5cbd0','❀','The Japanese secret to a long and happy life.'],
['b5','The Alchemist','Paulo Coelho','Fiction',2,'#aa6043','☼','A fable about following your dream.'],
['b6','Deep Work','Cal Newport','Productivity',3,'#204c63','▤','Rules for focused success in a distracted world.'],
['b7','Sapiens','Yuval Noah Harari','History',2,'#e9e0d0','◎','A brief history of humankind.'],
['b8','The Creative Act','Rick Rubin','Creativity',2,'#ccc8bd','○','A way of being.'],
['b9','Dune','Frank Herbert','Science fiction',3,'#c48854','◒','An epic journey on the desert planet Arrakis.'],
['b10','The Little Prince','Antoine de Saint-Exupéry','Fiction',2,'#667d9b','☆','A timeless story of wonder and friendship.']
].map(([id,title,author,category,copies,color,art,description])=>({id,title,author,category,copies,color,art,description})),members:[{id:'m1',name:'Aarav Sharma',email:'aarav@example.com',joined:datePlus(-40)},{id:'m2',name:'Ananya Patel',email:'ananya@example.com',joined:datePlus(-30)},{id:'m3',name:'Rohan Mehta',email:'rohan@example.com',joined:datePlus(-25)},{id:'m4',name:'Priya Singh',email:'priya@example.com',joined:datePlus(-15)},{id:'m5',name:'Ishaan Verma',email:'ishaan@example.com',joined:datePlus(-10)}],loans:[{id:'l1',bookId:'b1',memberId:'m1',issued:datePlus(-8),due:datePlus(6),returned:null},{id:'l2',bookId:'b2',memberId:'m2',issued:datePlus(-16),due:datePlus(-2),returned:null},{id:'l3',bookId:'b3',memberId:'m3',issued:datePlus(-7),due:datePlus(7),returned:null},{id:'l4',bookId:'b5',memberId:'m4',issued:datePlus(-9),due:datePlus(5),returned:null},{id:'l5',bookId:'b5',memberId:'m5',issued:datePlus(-10),due:datePlus(4),returned:null},{id:'l6',bookId:'b6',memberId:'m1',issued:datePlus(-20),due:datePlus(-6),returned:datePlus(-7)}],activity:[{text:'Ananya checked out Atomic Habits',time:Date.now()-3600000},{text:'A new chapter for your library. Welcome to Folio!',time:Date.now()-7200000}]});
let state,storageWarning='',savedSnapshot=null,recoveryRaw=null;
function validDate(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(value+'T12:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value}
function validText(value,max){return typeof value==='string'&&value.trim().length>0&&value.length<=max&&!/[\u0000-\u001f]/.test(value)}
function validateState(s){
 if(!s||s.version!==1||!['books','members','loans','activity'].every(k=>Array.isArray(s[k])))throw Error('Choose a valid Folio backup.');
 if(s.books.length>10000||s.members.length>10000||s.loans.length>50000||s.activity.length>1000)throw Error('This backup exceeds the workspace record limits.');
 const ids=new Set(),ms=new Set(),emails=new Set(),ls=new Set(),pairs=new Set(),counts=new Map();
 for(const b of s.books){if(!b||!validText(b.id,100)||ids.has(b.id)||!validText(b.title,150)||!validText(b.author,100)||!validText(b.category,60)||!Number.isInteger(b.copies)||b.copies<1||b.copies>999||(b.description!==undefined&&(typeof b.description!=='string'||b.description.length>2000))||(b.art!==undefined&&(typeof b.art!=='string'||b.art.length>20))||(b.color!==undefined&&(typeof b.color!=='string'||!/^#[0-9a-f]{6}$/i.test(b.color))))throw Error('Invalid book record. Check text, cover color, and 1–999 copies.');ids.add(b.id)}
 for(const m of s.members){if(!m||!validText(m.id,100)||ms.has(m.id)||!validText(m.name,100)||!validText(m.email,150)||! /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(m.email)||emails.has(m.email.trim().toLowerCase())||!validDate(m.joined))throw Error('Invalid member record. Check names, unique emails, and join dates.');ms.add(m.id);emails.add(m.email.trim().toLowerCase())}
 for(const l of s.loans){if(!l||!validText(l.id,100)||ls.has(l.id)||!ids.has(l.bookId)||!ms.has(l.memberId)||!validDate(l.issued)||!validDate(l.due)||l.due<l.issued||(l.returned!==null&&(!validDate(l.returned)||l.returned<l.issued)))throw Error('Invalid loan record or calendar date.');ls.add(l.id);if(l.returned===null){const pair=JSON.stringify([l.bookId,l.memberId]);if(pairs.has(pair))throw Error('A member cannot hold the same title twice.');pairs.add(pair);counts.set(l.bookId,(counts.get(l.bookId)||0)+1)}}
 for(const b of s.books)if((counts.get(b.id)||0)>b.copies)throw Error('Loans exceed book copies.');
 if(s.activity.some(a=>!a||!validText(a.text,500)||!Number.isFinite(a.time)||a.time<0))throw Error('Invalid activity record.');
}
try{savedSnapshot=localStorage.getItem(KEY);state=savedSnapshot?JSON.parse(savedSnapshot):seed();validateState(state);if(savedSnapshot===null){const json=JSON.stringify(state);localStorage.setItem(KEY,json);savedSnapshot=json}}catch(e){recoveryRaw=savedSnapshot;state=seed();storageWarning='Saved records could not be loaded. Your original data has been preserved. Open Settings to download it and restore a valid backup.'}
function commit(change,message,{replaceDamaged=false}={}){if(recoveryRaw!==null&&!replaceDamaged)throw Error('Restore a valid backup or reset the demo from Settings before saving. Download your original data first.');const next=structuredClone(state);change(next);validateState(next);try{if(localStorage.getItem(KEY)!==savedSnapshot)throw Error('CONFLICT');const json=JSON.stringify(next);localStorage.setItem(KEY,json);savedSnapshot=json}catch(err){if(err.message==='CONFLICT')throw Error('Your workspace changed in another tab. Reload this page before saving to keep those changes.');throw Error('Your browser could not save this change. Free storage or enable local storage and try again.')}state=next;storageWarning='';recoveryRaw=null;render();if(message)toast(message)}
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{if(!e.newValue)throw Error('Workspace was removed');const next=JSON.parse(e.newValue);validateState(next);state=next;savedSnapshot=e.newValue;recoveryRaw=null;storageWarning='';render();toast('Workspace updated from another tab.')}catch{storageWarning='Saved records changed in another tab and could not be loaded. Reload before making changes.';render()}});
function record(s,text){s.activity.unshift({text,time:Date.now()});s.activity=s.activity.slice(0,40)}
const active=()=>queries().loans,available=b=>b.copies-(queries().counts.get(b.id)||0),overdue=l=>!l.returned&&l.due<datePlus(0);
let page=location.hash.slice(1)||'overview',search='',category='All categories',availability='All availability',loanTab='active',loanSearch='',memberSearch='',sortBy='recent';
const pages=[['overview','▦','Overview'],['catalog','▥','Book catalog'],['members','♧','Members'],['loans','⇄','Lending records'],['insights','▤','Insights'],['settings','⚙','Settings']];
function cover(b){return `<div class="cover" style="background:${/^#[0-9a-f]{6}$/i.test(b.color)?b.color:'#274d40'};color:${['b2','b3','b4','b7','b8'].includes(b.id)?'#3a443c':'#f7ebcf'}"><small>FOLIO COLLECTION</small><strong>${esc(b.title)}</strong><span class="cover-art">${esc(b.art||'✦')}</span><span class="cover-author">${esc(b.author)}</span></div>`}
function bookCard(b){const a=available(b);return `<button class="book" data-book="${esc(b.id)}" aria-label="View ${esc(b.title)}"><div class="cover-area" style="background:${({b1:'#e9eeea',b2:'#f5f1e7',b3:'#f2eee6',b4:'#e8eff0',b5:'#f6ece5'})[b.id]||'#edf0e8'}">${cover(b)}</div><div class="book-title">${esc(b.title)}</div><div class="book-author">${esc(b.author)}</div><div class="book-meta"><span class="badge ${a?'':'amber'}">${a?'Available':'All borrowed'}</span><span>${a} of ${b.copies} copies</span></div></button>`}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><p class="eyebrow">YOUR LIBRARY, AT A GLANCE</p><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
const newBookButton='<button class="button primary" data-action="add-book"><span class="plus">+</span> Add a book</button>';
const checkoutButton='<button class="button secondary" data-action="checkout">⇄ &nbsp; Issue a book</button>';
function stats(){const total=state.books.reduce((n,b)=>n+b.copies,0),lent=active().length,late=active().filter(overdue).length;return `<div class="stats">${[['Total books',total,'▥',`${state.books.length} unique titles in your collection`],['Available to borrow',total-lent,'▧','Ready for their next reader'],['Books on loan',lent,'⇄','Stories out in the world'],['Active members',state.members.length,'♧',`${late} overdue loan${late===1?'':'s'} to follow up`]].map(([label,value,icon,foot])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value.toLocaleString()}</div><div class="stat-foot">${esc(foot)}</div></div>`).join('')}</div>`}
function loanRows(loans,full=false){return loans.map(l=>{const b=queries().books.get(l.bookId),m=queries().members.get(l.memberId);return `<tr><td><div class="mini-book"><span class="mini-cover" style="background:${/^#[0-9a-f]{6}$/i.test(b.color)?b.color:'#173d35'}">${esc(b.art||'✦')}</span><div><div class="cell-title">${esc(b.title)}</div><div class="cell-sub">${esc(b.author)}</div></div></div></td><td>${esc(m.name)}</td><td>${displayDate(l.due)}${full?' '+l.due.slice(0,4):''}</td><td><span class="badge ${l.returned?'':overdue(l)?'red':'amber'}">${l.returned?'Returned':overdue(l)?'Overdue':'On loan'}</span></td>${full?`<td>${l.returned?displayDate(l.returned):`<button class="row-button" data-return="${esc(l.id)}" aria-label="Return ${esc(b.title)} from ${esc(m.name)}">Return book</button> <button class="row-button" data-renew="${esc(l.id)}" aria-label="Renew ${esc(b.title)} for ${esc(m.name)}">Renew</button>`}</td>`:''}</tr>`}).join('')}
function loanTable(loans,full=false){return `<div class="table-wrap"><table><thead><tr><th>BOOK TITLE</th><th>BORROWER</th><th>DUE DATE</th><th>STATUS</th>${full?'<th>ACTION</th>':''}</tr></thead><tbody>${loanRows(loans,full)}</tbody></table>${!loans.length?'<div class="empty"><h3>All clear here</h3><p>No lending records match this view.</p></div>':''}</div>`}
function overview(){return heading('A good day for a new chapter.',"Welcome back, Harsh. Here’s what’s happening in your library.",checkoutButton+newBookButton)+`<section class="hero"><div class="hero-copy"><p class="eyebrow">A WELL-KEPT LIBRARY. A WELL-READ COMMUNITY.</p><h2>Less managing.<br>More <em>possibilities.</em></h2><figure class="hero-passage"><blockquote>${esc(passage('treasure').text)}</blockquote><figcaption>Henry David Thoreau · <cite>Walden</cite> · ${sourceButton(passage('treasure'))}</figcaption></figure><a class="button primary" href="#catalog">Explore the collection</a></div><div class="hero-art" aria-hidden="true"><div class="arch"></div><span class="hero-spark">✧</span><span class="plant">❧</span><div class="book-stack"><div class="stack-book">THE ART OF READING</div><div class="stack-book">a world of stories</div><div class="stack-book">ONE MORE CHAPTER</div></div></div></section>`+stats()+`<section><div class="section-heading"><div><h2>On the bookshelf</h2><p>A few favorites from your collection</p></div><a href="#catalog">View all books</a></div><div class="books">${state.books.slice(0,5).map(bookCard).join('')||'<div class="empty"><h3>Your first chapter starts here</h3><p>Add a book to begin your collection.</p></div>'}</div></section><div class="lower-grid"><section class="panel"><div class="section-heading"><h2>Recent lending</h2><a href="#loans">View records</a></div>${loanTable([...state.loans].filter(l=>!l.returned).slice(0,4))}</section><section class="panel"><div class="section-heading"><h2>Around the library</h2><span style="color:#9ca696">◷</span></div><div class="activity">${state.activity.slice(0,4).map((a,i)=>`<div class="activity-item"><span class="activity-symbol">${i%2?'✧':'⇄'}</span><p>${esc(a.text)}<small>${elapsed(a.time)}</small></p></div>`).join('')}<div class="activity-item"><span class="activity-symbol">♡</span><p><strong>Every book counts.</strong><br>${state.books.length} titles. Endless possibilities.<small>Your collection, thoughtfully organized.</small></p></div></div></section></div>`}
function elapsed(t){const n=Math.max(0,Math.floor((Date.now()-t)/60000));return n<1?'Just now':n<60?`${n} minutes ago`:n<1440?`${Math.floor(n/60)} hour${Math.floor(n/60)===1?'':'s'} ago`:`${Math.floor(n/1440)} day${Math.floor(n/1440)===1?'':'s'} ago`}
function catalog(){if(category!=='All categories'&&!state.books.some(b=>b.category===category))category='All categories';const cats=[...new Set(state.books.map(b=>b.category))].sort();return heading('The book catalog.','A home for every title, and a new discovery on every shelf.',newBookButton)+`<div class="toolbar"><div class="search"><span>⌕</span><input id="search" aria-label="Search books" placeholder="Search by title, author, or category…" value="${esc(search)}"></div><button class="button discover-button" data-action="surprise">✧ &nbsp; Find my next read</button><select id="category" aria-label="Filter by category">${['All categories',...cats].map(c=>`<option ${c===category?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="sort" aria-label="Sort books"><option value="recent" ${sortBy==='recent'?'selected':''}>Recently added</option><option value="title" ${sortBy==='title'?'selected':''}>Title A–Z</option><option value="author" ${sortBy==='author'?'selected':''}>Author A–Z</option></select><select id="availability" aria-label="Filter availability">${['All availability','Available','All borrowed'].map(c=>`<option ${c===availability?'selected':''}>${c}</option>`).join('')}</select></div><div class="section-heading"><p id="result-count"></p><span class="eyebrow">CURATED WITH CARE</span></div><div class="books catalog" id="catalog-grid"></div>`}
function filteredBooks(){const q=search.trim().toLowerCase(),books=state.books.filter(b=>(b.title+' '+b.author+' '+b.category).toLowerCase().includes(q)&&(category==='All categories'||b.category===category)&&(availability==='All availability'||(availability==='Available'?available(b)>0:available(b)===0)));if(sortBy==='title')books.sort((a,b)=>a.title.localeCompare(b.title));if(sortBy==='author')books.sort((a,b)=>a.author.localeCompare(b.author));return books}
function filterCatalog(){const books=filteredBooks();$('#result-count').textContent=books.length+' '+(books.length===1?'title':'titles')+' in your collection';$('#catalog-grid').innerHTML=books.length?books.map(bookCard).join(''):'<div class="empty"><h3>No books found</h3><p>Try another title, author, or filter.</p><button class="button secondary" data-action="clear-filters">Clear filters</button>'+passageNote('curious',true)+'</div>'}
function members(){return heading('A community of readers.','Keep your members close and their next great read closer.','<button class="button primary" data-action="add-member"><span class="plus">+</span> Add a member</button>')+`<div class="toolbar"><div class="search"><span>⌕</span><input id="member-search" aria-label="Search members" placeholder="Find a member by name or email…" value="${esc(memberSearch)}"></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>MEMBER</th><th>EMAIL</th><th>JOINED</th><th>ACTIVE LOANS</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody id="member-rows"></tbody></table></div></section>`}
function filterMembers(q=memberSearch){const ms=state.members.filter(m=>`${m.name} ${m.email}`.toLowerCase().includes(q.trim().toLowerCase()));$('#member-rows').innerHTML=ms.map(m=>{const loans=(queries().byMember.get(m.id)||[]);return `<tr><td><div class="mini-book"><span class="member-avatar">${esc(m.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><span class="cell-title">${esc(m.name)}</span></div></td><td>${esc(m.email)}</td><td>${displayDate(m.joined)} ${esc(m.joined.slice(0,4))}</td><td>${loans.length} book${loans.length===1?'':'s'}</td><td><span class="badge ${loans.some(overdue)?'red':''}">${loans.some(overdue)?'Overdue loan':'Active member'}</span></td><td><button class="row-button" data-edit-member="${esc(m.id)}" aria-label="Edit ${esc(m.name)}">Edit member</button></td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty">No members found.</div></td></tr>'}
function lending(){const ls=state.loans.filter(l=>loanTab==='all'||(loanTab==='returned'?l.returned:loanTab==='overdue'?overdue(l):!l.returned)).filter(l=>{const b=queries().books.get(l.bookId),m=queries().members.get(l.memberId);return (b.title+' '+m.name).toLowerCase().includes(loanSearch.trim().toLowerCase())});return heading('Every lending, accounted for.','Issue a book, track its journey, and welcome it back.','<button class="button primary" data-action="checkout">+ &nbsp; Issue a book</button>')+`<div class="tabs">${[['active','On loan'],['overdue','Overdue'],['returned','Returned'],['all','All records']].map(([id,name])=>`<button data-tab="${id}" class="${loanTab===id?'selected':''}">${name}${id==='overdue'?' · '+active().filter(overdue).length:''}</button>`).join('')}</div><div class="toolbar"><div class="search"><span>⌕</span><input id="loan-search" aria-label="Search loans" placeholder="Search loans by book or borrower…" value="${esc(loanSearch)}"></div><span class="results-label">${ls.length} record${ls.length===1?'':'s'}</span></div><section class="panel" id="loans-table">${loanTable(ls,true)}</section>`}
function insights(){const cats=[...new Set(state.books.map(b=>b.category))],max=Math.max(1,...cats.map(c=>state.books.filter(b=>b.category===c).length));return heading('A little perspective.','Understand your collection and the readers who bring it to life.')+stats()+`<div class="insights"><section class="panel"><div class="section-heading"><h2>Your collection, by category</h2></div><div class="chart">${cats.map(c=>{const n=state.books.filter(b=>b.category===c).length;return `<div class="bar-row"><span>${esc(c)}</span><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><strong>${n}</strong></div>`}).join('')}</div></section><section class="panel"><div class="section-heading"><h2>Circulation snapshot</h2></div><div class="chart"><p class="eyebrow">ALL-TIME CHECKOUTS</p><div class="insight-number">${state.loans.length}</div><p class="subtitle">${state.loans.filter(l=>l.returned).length} books returned to the shelves</p><br><br><p class="eyebrow">COLLECTION UTILIZATION</p><div class="insight-number">${Math.round(active().length/state.books.reduce((n,b)=>n+b.copies,0)*100)||0}%</div><p class="subtitle">of your copies are with readers right now</p></div></section></div>`}
function settings(){return heading('Make room for your library.','Your workspace, your records, your peace of mind.')+`${recoveryRaw!==null?'<section class="panel settings-card"><h3>Recover your original data</h3><p>Your saved file could not be validated. Download the untouched original before restoring a backup or resetting this workspace.</p><button class="button secondary" data-action="recover">Download original data</button></section>':''}<section class="panel settings-card"><h3>Your data stays with you.</h3><p>This portfolio demo saves books, members, and lending records in this browser. Export a JSON backup to keep a copy or move your workspace to another device.</p><button class="button primary" data-action="export">Export workspace</button> <button class="button secondary" data-action="import">Import backup</button><input type="file" id="import-file" accept="application/json,.json" hidden></section><section class="panel settings-card"><h3>Designed to be explored.</h3><p>Start fresh with the original demo books and readers. Export your workspace first if you want to keep your changes.</p><button class="button secondary danger" data-action="reset">Reset demo data</button></section><section class="panel settings-card"><h3>A note for your portfolio</h3><p>The interactive web demo uses browser storage. The downloadable project also includes a separate C++17 library engine with OOP, STL containers and algorithms, validated file persistence, and exception handling. See the README for build instructions and architecture.</p></section>`}
function render(){if(!pages.some(p=>p[0]===page))page='overview';$('#nav').innerHTML=pages.map(([id,icon,label])=>`<a href="#${id}" aria-label="${esc(label)}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span><span class="nav-text">${label}</span>${id==='loans'?`<span class="nav-count">${active().length}</span>`:''}</a>`).join('');$('#crumb').textContent=pages.find(p=>p[0]===page)[2];$('#main').innerHTML=(storageWarning?`<div class="storage-warning" role="alert">${esc(storageWarning)} <a href="#settings">Open Settings</a></div>`:'')+({overview,catalog,members,loans:lending,insights,settings}[page])()+(page==='overview'?'':pageNote());if(page==='catalog')filterCatalog();if(page==='members')filterMembers();document.title=pages.find(p=>p[0]===page)[2]+' · Folio';$('#notice-dot').hidden=!active().some(overdue)}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
const field=(name,label,type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" required ${extra}></label>`;
function openModal(title,fields,onSubmit,button='Save'){const d=$('#dialog'),revision=savedSnapshot;$('#modal-title').textContent=title;const noteId=({'A new story on the shelf.':'begin','Welcome a new reader.':'cat','Their next great read.':'novel','Back on the bookshelf.':'curious','A little more reading time.':'memory','Fine-tune the bookshelf.':'pictures','Keep reader details current.':'happy','Meet your new workspace.':'play'})[title];$('#fields').innerHTML=fields+(noteId?passageNote(noteId,true):'');$('#form-error').textContent='';$('#submit-button').textContent=button;$('#submit-button').hidden=!onSubmit;$('#form').onsubmit=e=>{e.preventDefault();try{if(!onSubmit){d.close();return}if(revision!==savedSnapshot)throw Error('This workspace changed in another tab. Close this dialog and reopen it to use the latest records.');onSubmit(new FormData(e.target));d.close()}catch(err){$('#form-error').textContent=err.message}};d.showModal();const first=d.querySelector('input,select');if(first)first.focus()}
function addBook(){openModal('A new story on the shelf.',field('title','Book title','text','maxlength="150"')+field('author','Author','text','maxlength="100"')+field('category','Category','text','maxlength="60"')+field('copies','Number of copies','number','min="1" max="999" value="1"'),f=>{const title=f.get('title').trim(),author=f.get('author').trim(),cat=f.get('category').trim(),copies=Number(f.get('copies'));if(!title||!author||!cat||!Number.isInteger(copies)||copies<1||copies>999)throw Error('Enter a title, author, category, and 1–999 copies.');commit(s=>{s.books.unshift({id:uid(),title,author,category:cat,copies,color:['#274d40','#a4684c','#526c87','#857b58'][s.books.length%4],art:'✦',description:'A new addition to your library.'});record(s,`${title} joined the collection`);},'Book added to your collection.');},'Add book')}
function addMember(){openModal('Welcome a new reader.',field('name','Full name','text','maxlength="100"')+field('email','Email address','email','maxlength="150"'),f=>{const name=f.get('name').trim(),email=f.get('email').trim().toLowerCase();if(!name||!email)throw Error('Please enter a name and email.');if(state.members.some(m=>m.email.toLowerCase()===email))throw Error('A member with this email already exists.');commit(s=>{s.members.unshift({id:uid(),name,email,joined:datePlus(0)});record(s,`${name} joined the reading community`);},'New member added.');},'Add member')}
function checkout(bookId){const books=state.books.filter(b=>available(b)>0);if(!books.length)return toast('All copies are currently on loan. Return a book first.');if(!state.members.length)return toast('Add a member before issuing a book.');openModal('Their next great read.',`<label class="field">Book<select name="book">${books.map(b=>`<option value="${esc(b.id)}" ${b.id===bookId?'selected':''}>${esc(b.title)} · ${available(b)} available</option>`).join('')}</select></label><label class="field">Borrower<select name="member">${state.members.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></label>`+field('due','Due date','date',`min="${datePlus(0)}" max="${datePlus(365)}" value="${datePlus(14)}"`),f=>{const book=state.books.find(b=>b.id===f.get('book')),member=state.members.find(m=>m.id===f.get('member')),due=f.get('due');if(!book||!member||available(book)<1)throw Error('This book or member is no longer available.');if(!validDate(due)||due<datePlus(0)||due>datePlus(365))throw Error('Choose a due date between today and one year from now.');if(active().some(l=>l.bookId===book.id&&l.memberId===member.id))throw Error('This member already has a copy of this book.');commit(s=>{s.loans.unshift({id:uid(),bookId:book.id,memberId:member.id,issued:datePlus(0),due,returned:null});record(s,`${member.name} checked out ${book.title}`);},'Book issued. A new chapter begins.');},'Issue book')}
function bookDetail(id){const b=state.books.find(b=>b.id===id);if(!b)return;if($('#dialog').open)$('#dialog').close();openModal(b.title,`<div class="detail-cover">${cover(b)}<div class="detail-info"><p>${esc(b.author)}</p><p>${esc(b.category)}</p><span class="badge ${available(b)?'':'amber'}">${available(b)} of ${b.copies} copies available</span></div></div><p class="subtitle">${esc(b.description||'Part of your Folio collection.')}</p>${passageNote('pictures',true)}<button type="button" class="button secondary detail-edit" data-edit-book="${esc(b.id)}">Edit book details</button>`,available(b)?()=>{setTimeout(()=>checkout(b.id),0)}:null,'Issue this book')}
function returnBook(id){const l=state.loans.find(l=>l.id===id);if(!l||l.returned)return;const b=queries().books.get(l.bookId),m=queries().members.get(l.memberId);openModal('Back on the bookshelf.',`<p class="subtitle">Confirm that <strong>${esc(m.name)}</strong> has returned <strong>${esc(b.title)}</strong>. The copy will be available to borrow again.</p>`,()=>commit(s=>{s.loans.find(l=>l.id===id).returned=datePlus(0);record(s,`${m.name} returned ${b.title}`);},'Return recorded. Ready for the next reader.'),'Confirm return')}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`folio-backup-${datePlus(0)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Workspace backup exported.')}
const actions={'add-book':addBook,'add-member':addMember,checkout:()=>checkout(),export:exportData,import:()=>$('#import-file').click(),reset:()=>openModal('Start a fresh chapter?',`<p class="subtitle">This replaces your current workspace with the original demo records. Export a backup first to keep your changes.</p>`,()=>{category='All categories';availability='All availability';commit(s=>Object.assign(s,seed()),'Demo workspace restored.',{replaceDamaged:true})},'Reset workspace')};
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]'),b=e.target.closest('[data-book]'),r=e.target.closest('[data-return]'),t=e.target.closest('[data-tab]');if(a)actions[a.dataset.action]?.();if(b)bookDetail(b.dataset.book);if(r)returnBook(r.dataset.return);if(t){loanTab=t.dataset.tab;render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;filterCatalog()}if(e.target.id==='member-search'){memberSearch=e.target.value;filterMembers()}if(e.target.id==='loan-search'){loanSearch=e.target.value;const holder=document.createElement('div');holder.innerHTML=lending();$('#loans-table').innerHTML=holder.querySelector('#loans-table').innerHTML;$('.results-label').textContent=holder.querySelector('.results-label').textContent}});
document.addEventListener('change',async e=>{if(e.target.id==='sort'){sortBy=e.target.value;filterCatalog()}if(e.target.id==='category'){category=e.target.value;filterCatalog()}if(e.target.id==='availability'){availability=e.target.value;filterCatalog()}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Choose a backup smaller than 2 MB.');const incoming=JSON.parse(await file.text());if(incoming.version!==1||!Array.isArray(incoming.books)||!Array.isArray(incoming.members)||!Array.isArray(incoming.loans)||!Array.isArray(incoming.activity))throw Error('Choose a valid Folio backup.');validateState(incoming);openModal('Restore this workspace?',`<p class="subtitle">Replace current records with ${incoming.books.length} books, ${incoming.members.length} members, and ${incoming.loans.length} loans from this backup.</p>`,()=>{category='All categories';availability='All availability';commit(s=>{for(const k of ['version','books','members','loans','activity'])s[k]=incoming[k]},'Workspace restored.',{replaceDamaged:true})},'Restore backup')}catch(err){toast('Import failed: '+err.message)}e.target.value=''}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';search='';render();window.scrollTo(0,0)});
$('#close-modal').onclick=$('#cancel-modal').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close()}});$('#notifications').onclick=()=>{loanTab='overdue';if(page==='loans')render();else location.hash='loans'};$('#profile').onclick=()=>location.hash='settings';$('#guide').onclick=()=>openModal('Meet your new workspace.',`<p class="subtitle">Browse the catalog to find a book. Add readers under Members, then use Issue a book to start a loan. Lending records keep due dates and returns in one place.<br><br>Your changes are saved in this browser. Settings lets you export a backup whenever you like.</p>`,null);render();

function editBook(id){const b=state.books.find(b=>b.id===id);if(!b)return;$('#dialog').close();const used=b.copies-available(b);openModal('Fine-tune the bookshelf.',field('title','Book title','text','maxlength="150" value="'+esc(b.title)+'"')+field('author','Author','text','maxlength="100" value="'+esc(b.author)+'"')+field('category','Category','text','maxlength="60" value="'+esc(b.category)+'"')+field('copies','Total copies','number','min="'+Math.max(1,used)+'" max="999" value="'+b.copies+'"')+'<p class="subtitle">'+used+' copies currently on loan. Total copies cannot be lower than active loans.</p>',f=>commit(s=>{const target=s.books.find(x=>x.id===id);Object.assign(target,{title:f.get('title').trim(),author:f.get('author').trim(),category:f.get('category').trim(),copies:Number(f.get('copies'))});record(s,'Updated '+target.title)},'Book details updated.'),'Save changes')}
function editMember(id){const m=state.members.find(m=>m.id===id);if(!m)return;openModal('Keep reader details current.',field('name','Full name','text','maxlength="100" value="'+esc(m.name)+'"')+field('email','Email address','email','maxlength="150" value="'+esc(m.email)+'"'),f=>commit(s=>{const target=s.members.find(x=>x.id===id);Object.assign(target,{name:f.get('name').trim(),email:f.get('email').trim().toLowerCase()});record(s,'Updated member details for '+target.name)},'Member details updated.'),'Save changes')}
function renewLoan(id){const l=state.loans.find(l=>l.id===id);if(!l||l.returned)return;const b=queries().books.get(l.bookId);const base=l.due>datePlus(0)?new Date(l.due+'T12:00:00'):new Date();base.setDate(base.getDate()+14);const due=base.getFullYear()+'-'+String(base.getMonth()+1).padStart(2,'0')+'-'+String(base.getDate()).padStart(2,'0');openModal('A little more reading time.', '<p class="subtitle">Renew <strong>'+esc(b.title)+'</strong>. Current due date: '+displayDate(l.due)+'.</p><br>'+field('due','New due date','date','min="'+(l.due>datePlus(0)?l.due:datePlus(0))+'" max="'+datePlus(365)+'" value="'+due+'"'),f=>{const date=f.get('due');if(!validDate(date)||date<=l.due||date<datePlus(0)||date>datePlus(365))throw Error('Choose a later due date, within one year of today.');commit(s=>{s.loans.find(x=>x.id===id).due=date;record(s,'Renewed '+b.title+' until '+displayDate(date))},'Loan renewed. Enjoy the next chapter.')},'Renew loan')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-edit-book]'),m=e.target.closest('[data-edit-member]'),l=e.target.closest('[data-renew]');if(b)editBook(b.dataset.editBook);if(m)editMember(m.dataset.editMember);if(l)renewLoan(l.dataset.renew)});
actions.recover=()=>{const blob=new Blob([recoveryRaw||''],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='folio-original-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};

document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus()}});
let renderedDay=datePlus(0);window.addEventListener('focus',()=>{if(renderedDay!==datePlus(0)){renderedDay=datePlus(0);render()}});

actions.surprise=()=>{const books=filteredBooks().filter(b=>available(b)>0);if(!books.length)return toast('No available titles in these filters. Clear filters to explore more books.');const values=new Uint32Array(1);crypto.getRandomValues(values);bookDetail(books[values[0]%books.length].id)};
actions['clear-filters']=()=>{search='';category='All categories';availability='All availability';render();$('#search').focus()};
document.addEventListener('click',e=>{const source=e.target.closest('[data-source]');if(source)showSource(source.dataset.source);if(e.target.closest('[data-literary-library]'))showPassages();if(e.target.closest('[data-another-passage]')){quoteOffsets[page]=(quoteOffsets[page]||0)+1;$('.page-passage').outerHTML=pageNote();$('.page-passage').querySelector('[data-another-passage]').focus()}});
$('#close-source').onclick=()=>$('#source-dialog').close();$('#source-dialog').addEventListener('click',e=>{if(e.target===$('#source-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.target.closest('input,select,textarea,[contenteditable="true"]')&&!$('#dialog').open&&!$('#source-dialog').open){const target=$('#search')||$('#member-search')||$('#loan-search');if(target){e.preventDefault();target.focus()}}});
$('#guide').insertAdjacentHTML('afterend','<br><button class="source-library-button" data-literary-library>Literary discoveries</button>');
